const today=()=>new Date().toISOString().slice(0,10)
const defaultSettings:Settings={id:'settings',ownerName:'Wendy',businessName:'Awenia',hourlyRate:1500,targetProfitRate:.25,indirectRate:.05,commissionType:'none',commissionValue:0,rounding:500}
